import sys

def solve():
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n = int(line.strip())
    except ValueError:
        return

    sums = {}

    def ask(i, j):
        print(f"? {i} {j}")
        sys.stdout.flush()
        resp = sys.stdin.readline()
        while resp and not resp.strip():
            resp = sys.stdin.readline()
        if not resp:
            return None
        return int(resp.strip())

    s12 = ask(1, 2)
    s13 = ask(1, 3)
    s23 = ask(2, 3)

    a = [0] * (n + 1)
    a[1] = (s12 + s13 - s23) // 2
    a[2] = s12 - a[1]
    a[3] = s13 - a[1]

    for i in range(4, n + 1):
        sij = ask(1, i)
        a[i] = sij - a[1]

    result = []
    for i in range(1, n + 1):
        result.append(str(a[i]))

    print("! " + " ".join(result))
    sys.stdout.flush()

if __name__ == "__main__":
    solve()
